import { test, expect } from '@playwright/test';

test.describe('Lazy-loaded components', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should load lazy components smoothly', async ({ page }) => {
    await page.waitForSelector('img[data-lazyload]'); // Wait for the lazy-loaded image to appear
    const lazyImage = page.getByRole('img', { name: /lazy loaded image/i });
    await expect(lazyImage).toBeVisible();
    await expect(lazyImage).toHaveAttribute('src', /actual-image-url/i); // Check if the src is set correctly
  });

  test('should not cause layout shift on lazy load', async ({ page }) => {
    const initialLayout = await page.evaluate(() => document.body.innerHTML);
    await page.waitForSelector('img[data-lazyload]');
    const lazyImage = page.getByRole('img', { name: /lazy loaded image/i });
    await expect(lazyImage).toBeVisible();
    const finalLayout = await page.evaluate(() => document.body.innerHTML);
    expect(initialLayout).toEqual(finalLayout); // Ensure layout remains the same
  });
});
